using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    private readonly ModelImport _importModel=new();
    public void add_property_file_slot(Control owner,Control parent,Resource property,Resource actor,Resource definition){var get=Callable.From(()=>_data.get_value(actor,property.Get("id").AsStringName(),default));var set=Callable.From<Variant>(value=>{if(!owner.Get("_syncing").AsBool())_batch.edit(Ui<RefCounted>(owner,"property_batch"),actor,property.Get("id").AsStringName(),value);});add_file_resource_slot(owner,parent,property,get,set,default,default);}
    public void add_object_file_slot(Control owner,Resource actor,Resource data,Resource definition,Resource property,VBoxContainer parent){var row=new HBoxContainer();parent.AddChild(row);var get=Callable.From(()=>animated_object_value(owner,actor,data,definition,property));var set=Callable.From<Variant>(value=>{_timeline.edit_object_property(Ui<RefCounted>(owner,"model"),actor,data,definition,property.Get("id").AsStringName(),value);if(property.Get("options").AsGodotDictionary().GetValueOrDefault("refresh_inspector",false).AsBool())owner.Call("_rebuild_selected");});Variant parameters=default;if(property.Get("id").AsString()=="shader_path"&&_definitions.find_property(definition,"uniforms")!=null){string id=actor.Get("id").AsString();var path=_animation.path_to_object(actor,data);parameters=Callable.From(()=>owner.Call("shader_workspace_parameter_binding",id,path,actor).AsGodotDictionary());}add_file_resource_slot(owner,row,property,get,set,default,parameters);}
    public Settings read_file_parameters(Resource data,Resource definition){var property=_definitions.find_property(definition,"uniforms");return property!=null?_definitions.value_for(data,property).AsGodotDictionary().Duplicate(true):new Settings();}
    public void add_saved_object_file_slot(Control owner,Resource data,Resource definition,Resource property,VBoxContainer parent,Resource? root){var row=new HBoxContainer();parent.AddChild(row);Variant parameters=default;if(property.Get("id").AsString()=="shader_path"&&_definitions.find_property(definition,"uniforms")!=null){var reader=Callable.From(()=>read_file_parameters(data,definition));var writer=Callable.From<StringName,Variant,string,Variant>((name,value,mode,original)=>set_file_uniform(owner,data,name,value,mode,original));parameters=Callable.From(()=>new Settings{["values"]=read_file_parameters(data,definition),["reader"]=reader,["writer"]=writer});}add_file_resource_slot(owner,row,property,Callable.From(()=>_data.object_get_value(data,property.Get("id").AsStringName(),default)),Callable.From<Variant>(value=>set_file_value(owner,data,definition,property,root,value)),default,parameters);}
    public void add_uniform_texture_slot(Control owner,Resource actor,Resource data,Resource definition,VBoxContainer parent,StringName name,string title){var property=_properties.create(name,title,"",true);property.Set("object_type",new StringName("image"));property.Set("options",shader_texture_options());var uniforms=_definitions.find_property(definition,"uniforms");if(uniforms==null)return;add_shader_texture_uniform(owner,parent,property,Callable.From(()=>animated_object_value(owner,actor,data,definition,uniforms).AsGodotDictionary().GetValueOrDefault(name,"")),Callable.From<Variant>(value=>{_timeline.edit_shader_uniform(Ui<RefCounted>(owner,"model"),actor,data,definition,name,value,"edit",default);owner.CallDeferred("_rebuild_selected");}),actor,null);}
    public void add_file_uniform_texture(Control owner,Resource data,VBoxContainer parent,StringName name,string title){var property=_properties.create(name,title,"",true);property.Set("options",shader_texture_options());add_shader_texture_uniform(owner,parent,property,Callable.From(()=>_data.object_get_value(data,"uniforms",new Settings()).AsGodotDictionary().GetValueOrDefault(name,"")),Callable.From<Variant>(value=>{set_file_uniform(owner,data,name,value,"edit",default);owner.CallDeferred("inspect_file_resource",data.ResourcePath);}),null,data);}
    public void add_object_font(Control owner,Resource actor,Resource data,Resource definition,Resource property,VBoxContainer parent){add_label(parent,property.Get("label").AsString());var selector=FontEditor(owner,parent,_definitions.value_for(data,property).ToString(),value=>_timeline.edit_object_property(Ui<RefCounted>(owner,"model"),actor,data,definition,property.Get("id").AsStringName(),value));owner.Get("_updaters").AsGodotArray().Add(Callable.From(()=>selector.Text=_definitions.value_for(data,property).ToString()));}
    public bool add_special_file_value(Control owner,Resource data,Resource definition,Resource property,VBoxContainer parent,Resource? root){if(property.Get("object_type").AsString().Length>0){int depth=owner.Get("_resource_depth").AsInt32();if(depth>=6){add_label(parent,"Reference depth limit — open the linked resource directly.");return true;}owner.Set("_resource_depth",depth+1);try{add_file_object_reference(owner,data,property,parent,root??data);}finally{owner.Set("_resource_depth",depth);}return true;}var options=property.Get("options").AsGodotDictionary();if(options.GetValueOrDefault("natural_material",false).AsBool()){add_natural_material_editor(owner,null,data,definition,property,parent,root);return true;}if(options.GetValueOrDefault("system_font",false).AsBool()){add_label(parent,property.Get("label").AsString());var selector=FontEditor(owner,parent,_definitions.value_for(data,property).ToString(),value=>set_file_value(owner,data,definition,property,root,value));owner.Get("_updaters").AsGodotArray().Add(Callable.From(()=>selector.Text=_definitions.value_for(data,property).ToString()));return true;}if(options.GetValueOrDefault("shader_uniforms",false).AsBool()){add_file_shader_uniforms(owner,data,parent);return true;}return false;}
    public void add_natural_material_editor(Control owner,Resource? actor,Resource data,Resource definition,Resource property,VBoxContainer parent,Resource? root){var editor=new ActorNaturalMaterialEditor();parent.AddChild(editor);var reader=Callable.From(()=>_definitions.value_for(data,property).AsGodotDictionary().Duplicate(true));var writer=Callable.From<Settings,string,Settings>((value,mode,original)=>write_natural_material(owner,actor,data,definition,property,root,value,mode,original));editor.Call("setup",reader,writer,actor==null?"saved":data.ResourcePath.Length>0?"linked":"local");owner.Get("_updaters").AsGodotArray().Add(new Callable(editor,"sync_from_source"));}
    public void assign_file_object_value(Control owner,Resource data,StringName key,Variant value,Resource root){_data.set_value(data,key,_data.copy_value(value));root.EmitChanged();var target=data.ResourcePath.Length>0&&!data.ResourcePath.Contains("::",StringComparison.Ordinal)?data:root;if(target.ResourcePath.Length>0)ResourceSaver.Save(target,target.ResourcePath);Ui<RefCounted>(owner,"model").EmitSignal("changed");}
    public Settings prepare_model_unique(Control owner,Variant getter){var value=Invoke(owner,getter);if(value.VariantType!=Variant.Type.String||value.AsString().Length==0)return new Settings();var document=_importModel.load_document(value);return document.Get("components").AsGodotArray().Count>0?new Settings{["document"]=document,["suggested"]=value.AsString().GetFile().GetBaseName()+" unique"}:new Settings();}
    public void finish_model_unique(Control owner,Variant setter,Settings plan,Settings result){if(result.GetValueOrDefault("cancelled",true).AsBool())return;string path=result.GetValueOrDefault("path","").AsString();if(path.Length>0&&ResourceSaver.Save(plan["document"].As<Resource>(),path)==Error.Ok){Invoke(owner,setter,path);RefreshFilesystem();}}
}
